INSERT INTO `t_post` VALUES (97, 'aixueforever', 'aixueforever-71925', '什么是NUMA架构 简单来说，NUMA（Non-Uniform Memory Access，非统一内存访问架构） 是一种为了提高多处理器系统（多核 CPU）处理效率的内存设计方案。 在传统的架构中，所有处理器访问内存的速度是一样的；而在 NUMA 架构下，处理器访问“离自己近”的内存比访问“远程”内存要快得多。 1. 为什么会出现 NUMA？ 在早期的 UMA（Uniform Memory A', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:01:12', '2026-03-02 18:01:12');
INSERT INTO `t_post` VALUES (98, 'AI-Frontiers 公#众#号：AI-Frontiers', 'ai-frontiers-ai-frontiers-71947', '原文: https://mp.weixin.qq.com/s/5viL2gJE3IfmVS1WxTlZAQ 关注gzh: AI-Frontiers 往期文章推荐 小白也能看懂的RL-PPO 收藏！强化学习从入门到封神：5 本经典教材 + 8 大实战项目 + 7个免费视频，一站式搞定 小白也能看懂的RLHF：基础篇 小白也能看懂的RLHF-PPO：原理篇 小白也能看懂的LLM-RL算法：PPO/D', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:01:12', '2026-03-02 18:01:12');
INSERT INTO `t_post` VALUES (99, 'MyBatis-mybatis入门与增删改查', 'mybatis-mybatis-71969', '了解Mybatis Mybatis是一个持久层框架，半自动化ORM（Hibernate属于全自动化ORM）。 Mybatis的特点： 支持定制化sql、存储过程、基本映射以及高级映射 避免了几乎所有的JDBC代码中手动设置参数以及获取结果集 支持XML开发，也支持注解式开发 将接口和Java的pojo映射成数据库中的记录 体积小，易上手 完全做到sql解耦 提供了基本映射标签和高级映射标签 提', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:01:12', '2026-03-02 18:01:12');
INSERT INTO `t_post` VALUES (100, 'FastAPI压力测试实战：Locust模拟真实用户并发及优化建议', 'fastapilocust-72013', '嘿，朋友们👋 你有没有遇到过这种情况：接口本地跑得飞快，一上线就被用户吐槽“卡成PPT”？或者更惨，直接502宕机，半夜被报警电话炸醒？ 上个月我就差点翻车——给一个活动写的FastAPI接口，预估峰值也就几百QPS，结果流量冲上来时数据库连接数直接爆了，整个服务瘫了半小时。事后复盘才发现：不是代码写得不好，而是根本没做压力测试！ 今天咱们就坐下来聊聊，怎么给FastAPI做压测，以及扛住高并', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:01:12', '2026-03-02 18:01:12');
INSERT INTO `t_post` VALUES (101, 'suiyuan129', 'suiyuan129-72043', 'kmp算法:我们所忽略的字符串匹配本质 众所周知，kmp算法是一个精妙且广为人知的算法，但我们似乎仅仅只是硬记或只是知晓它通过next数组与前后缀去完成匹配，根本没有看到它所精妙的地方。 不久前，我在刷视频时偶然看见了介绍kmp算法的视频，就开始推演我很久之前所学的kmp算法，推演着推演着我发现了我之前所未发现的字符串的匹配本质，以下我开始讲解。 字符串匹配，有一个资源串与目标串，我们先统一术语', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:01:12', '2026-03-02 18:01:12');
