INSERT INTO `t_post` VALUES (128, 'MyBatis-mybatis入门与增删改查', 'mybatis-mybatis-58816', '# 了解Mybatis Mybatis是一个持久层框架，半自动化ORM（Hibernate属于全自动化ORM）。 Mybatis的特点： - 支持定制化sql、存储过程、基本映射以及高级映射 - 避免了几乎所有的JDBC代码中手动设置参数以及获取结果集 - 支持XML开发，也支持注解式开发 - 将接口和Java的pojo映射成数据库中的记录 - 体积小，易上手 - 完全做到sql解', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:29:19', '2026-03-02 18:29:19');
INSERT INTO `t_post` VALUES (129, 'FastAPI压力测试实战：Locust模拟真实用户并发及优化建议', 'fastapilocust-58833', '嘿，朋友们👋 你有没有遇到过这种情况：接口本地跑得飞快，一上线就被用户吐槽“卡成PPT”？或者更惨，直接502宕机，半夜被报警电话炸醒？ 上个月我就差点翻车——给一个活动写的FastAPI接口，预估峰值也就几百QPS，结果流量冲上来时数据库连接数直接爆了，整个服务瘫了半小时。事后复盘才发现：**不是代码写得不好，而是根本没做压力测试！** 今天咱们就坐下来聊聊，怎么给FastAPI做压测，以及扛', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:29:19', '2026-03-02 18:29:19');
INSERT INTO `t_post` VALUES (130, 'suiyuan129', 'suiyuan129-58851', '# kmp算法:我们所忽略的字符串匹配本质 众所周知，kmp算法是一个精妙且广为人知的算法，但我们似乎仅仅只是硬记或只是知晓它通过next数组与前后缀去完成匹配，根本没有看到它所精妙的地方。 不久前，我在刷视频时偶然看见了介绍kmp算法的视频，就开始推演我很久之前所学的kmp算法，推演着推演着我发现了我之前所未发现的字符串的匹配本质，以下我开始讲解。 字符串匹配，有一个资源串与目标串，我们先', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:29:19', '2026-03-02 18:29:19');
INSERT INTO `t_post` VALUES (131, '如何通过 C# 实现 PDF 文本提取？', 'c-pdf-58869', '在日常办公和开发中，从 PDF 文件中提取文本是一项高频需求。手动复制粘贴不仅耗时，而且面对大量文档时效率极低。传统的自动化方案往往依赖 Adobe Reader 等外部组件，不仅部署麻烦，遇到加密或扫描件更是难以处理。 本文将介绍如何使用免费库 **Free Spire.PDF for .NET** ，无需安装任何 PDF 阅读器，轻松实现高精度、高可靠性的 PDF 文本提取。我们将从方案对比', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:29:19', '2026-03-02 18:29:19');
INSERT INTO `t_post` VALUES (132, '鸿蒙应用开发UI基础第十五节：文本输入组件核心讲解与实战', 'ui-13418', '## 【学习目标】 - 区分TextInput、TextArea、Search三大组件的核心差异，掌握精准的场景选型逻辑； - 掌握三大组件的基础创建、输入类型配置、样式定制，适配各类输入开发场景； - 熟练绑定核心通用事件，实现输入数据的获取与业务处理； - 掌握Search专属能力与三大组件控制器的精细控制用法； - 掌握输入内容过滤的核心实现方式，保证输入内容合法性； - 具备输', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:36:53', '2026-03-02 18:36:53');
INSERT INTO `t_post` VALUES (133, '公司给团队配了Cursor，然后开始裁员：一个残酷但必须面对的真相', 'cursor-13447', '昨天晚上，一个做了5年Java的朋友给我发微信： \"公司刚给我们配了Cursor和ChatGPT Plus，说要提升开发效率。今天早上，HR找我谈话，说团队要优化20%的人。\" 他问我：\"是不是AI真的要替代程序员了？\" 我沉默了很久。 这不是个例。 最近听到太多类似的消息： - 某互联网大厂，研发团队从50人优化到35人 - 某外包公司，初级开发岗位招聘冻结 - 某创业公司，2个', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:36:53', '2026-03-02 18:36:53');
INSERT INTO `t_post` VALUES (134, 'aixueforever', 'aixueforever-13467', '# 什么是NUMA架构 简单来说，**NUMA（Non-Uniform Memory Access，非统一内存访问架构）** 是一种为了提高多处理器系统（多核 CPU）处理效率的内存设计方案。 在传统的架构中，所有处理器访问内存的速度是一样的；而在 NUMA 架构下，处理器访问“离自己近”的内存比访问“远程”内存要快得多。 ### 1. 为什么会出现 NUMA？ 在早期的 **UMA（Un', '', 74, NULL, 1, 'draft', 'immediate', NULL, 0, 0, 0, 0, 0, NULL, NULL, NULL, NULL, NULL, 0, 0, 0, 0, '2026-03-02 18:36:53', '2026-03-02 18:36:53');
